def make_dataset(N, train_length):
    # generates 2 ** N - 1 timeseries with constant increasing values
    n = 2**N - 1
    targets = np.ones((n, train_length))
    for i in range(0, n):
        targets[i, :] = targets[i, :] * i

    ds = gluonts.dataset.common.ListDataset(
        data_iter=[
            {"start": "2012-01-01", "target": targets[i, :]} for i in range(n)
        ],
        freq="1D",
    )

    return ds

def load_checkpoint(checkpoint_path, model, optimizer=None, is_old=False, epochs=10000):
  assert os.path.isfile(checkpoint_path)
  checkpoint_dict = torch.load(checkpoint_path, map_location='cpu')
  iteration = checkpoint_dict['iteration']
  learning_rate = checkpoint_dict['learning_rate']
  if optimizer is not None:
    if not is_old:
      optimizer.load_state_dict(checkpoint_dict['optimizer'])
    else:
      new_opt_dict = optimizer.state_dict()
      new_opt_dict_params = new_opt_dict['param_groups'][0]['params']
      new_opt_dict['param_groups'] = checkpoint_dict['optimizer']['param_groups']
      new_opt_dict['param_groups'][0]['params'] = new_opt_dict_params
      optimizer.load_state_dict(new_opt_dict)
  saved_state_dict = checkpoint_dict['model']
  if hasattr(model, 'module'):
    state_dict = model.module.state_dict()
  else:
    state_dict = model.state_dict()
  new_state_dict= {}
  for k, v in state_dict.items():
    try:
      new_state_dict[k] = saved_state_dict[k]
    except:
        if k == 'step':
            new_state_dict[k] = iteration * epochs
        else:
            logger.info("%s is not in the checkpoint" % k)
            new_state_dict[k] = v

  if hasattr(model, 'module'):
    model.module.load_state_dict(new_state_dict, strict=False)
  else:
    model.load_state_dict(new_state_dict, strict=False)
  logger.info("Loaded checkpoint '{}' (iteration {})" .format(
    checkpoint_path, iteration))
  return model, optimizer, learning_rate, iteration

