def run_model_in_thread(model, in_out, tokenizer, result, warm_up, num_beams, input_ids, out_len, actual_in_len, num_trials, load_time, lookahead):
    for i in range(num_trials + warm_up):
        st = time.perf_counter()
        if lookahead:
            output_ids = model.generate(input_ids, lookahead=2, do_sample=False, max_matching_ngram_size=2, max_new_tokens=out_len,
                                        min_new_tokens=out_len, num_beams=num_beams)
        else:
            output_ids = model.generate(input_ids, do_sample=False, max_new_tokens=out_len,
                                        min_new_tokens=out_len, num_beams=num_beams)
        torch.xpu.synchronize()
        end = time.perf_counter()
        output_ids = output_ids.cpu()
        print("model generate cost: " + str(end - st))
        output = tokenizer.batch_decode(output_ids)
        print(output[0])
        torch.xpu.empty_cache()
        actual_out_len = output_ids.shape[1] - actual_in_len
        if i >= warm_up:
            if lookahead or os.environ.get("IPEX_LLM_PERFORMANCE_MODE", None) == "1":
                result[in_out].append([model.first_token_time, (end - st - model.first_token_time)/(model.n_token_generated - 1), 0,
                                       actual_in_len, actual_out_len, load_time, 0])
            else:
                result[in_out].append([model.first_cost, model.rest_cost_mean, model.encoder_time,
                                        actual_in_len, actual_out_len, load_time, model.peak_memory])

def eval_subject(
        self,
        subject_name,
        test_df,
        eval_type="validation", # "test","validation",
        dev_df=None,
        few_shot=False,
        cot=True,
    ):
        if eval_type == "validation":
            correct_num = 0

            if few_shot:
                history = self.generate_few_shot_prompt(subject_name, dev_df, cot=cot)
            else:
                history = []

            answers = list(test_df['answer'])

            for row_index, row in tqdm(test_df.iterrows(), total=len(test_df)):
                question = self.format_example(row, include_answer=False, cot=cot)

                if few_shot:
                    response, _ = self.model.chat(self.tokenizer, question, do_sample=False, history=history)
                    response = response.strip()
                    # For ChatGLM, we use answer extraction in answer-only mode too.
                    ans, direct_extract = self.extract_cot_answer(row, response)
                else:   # zero-shot by extracting answer from distribution
                    ans = self.generate_dist(self.model, self.tokenizer, question, do_sample=False, max_length=2048, history=history)

                if ans == answers[row_index]:
                    correct_num += 1

            correct_ratio = 100*correct_num/len(answers)

            return correct_ratio, None
        elif eval_type == "test":
            answers = {}
            for i, row in tqdm(test_df.iterrows(), total=len(test_df)):
                question = self.format_example(row, include_answer=False, cot=cot)
                answers[str(i)] = self.generate_dist(self.model, self.tokenizer, question, do_sample=False, max_length=2048, history=[])

            return None, answers

