def test_from_jax_module(bs_ic_oc, from_class_and_args, module_type, backend_fw):
    # smoke test
    if backend_fw not in ["jax"]:
        # Converters not implemented in numpy
        pytest.skip()

    batch_shape, input_channels, output_channels = bs_ic_oc
    with ivy.utils.backend.ContextManager(backend_fw) as ivy_backend:
        x = ivy_backend.astype(
            ivy_backend.linspace(
                ivy_backend.zeros(batch_shape),
                ivy_backend.ones(batch_shape),
                input_channels,
            ),
            "float32",
        )
    native_module_class = NATIVE_MODULES["jax"][module_type]
    module_converter = FROM_CONVERTERS["jax"][module_type]
    module_converter = get_converter(ivy, FROM_CONVERTERS["jax"][module_type])
    if from_class_and_args:
        ivy_module = module_converter(
            native_module_class,
            instance_args=[x],
            constructor_kwargs={
                "in_size": input_channels,
                "out_size": output_channels,
            },
        )
    else:
        if module_type == "haiku":

            def forward_fn(*a, **kw):
                model = native_module_class(input_channels, output_channels)
                return model(x.data)

            native_module = hk.transform(forward_fn)
        else:
            native_module = native_module_class(
                in_size=input_channels, out_size=output_channels
            )

        fw_kwargs = {}
        if module_type == "haiku":
            fw_kwargs["params_hk"] = native_module.init(0, x)
        else:
            fw_kwargs["params_fx"] = native_module.init(jax.random.PRNGKey(0), x.data)
        ivy_module = module_converter(native_module, **fw_kwargs)

    def loss_fn(v_=None):
        out = ivy_module(x, v=v_)
        return ivy_backend.mean(out)

    # train
    loss_tm1 = 1e12
    loss = None
    grads = None
    loss_fn()  # for on-call mode

    with ivy.utils.backend.ContextManager(backend_fw) as ivy_backend:
        for _ in range(10):
            loss, grads = ivy_backend.execute_with_gradients(loss_fn, ivy_module.v)
            ivy_module.v = ivy_backend.gradient_descent_update(
                ivy_module.v, grads, 1e-3
            )
            assert loss < loss_tm1
            loss_tm1 = loss

        # type test
        assert ivy_backend.is_array(loss)
        assert isinstance(grads, ivy_backend.Container)
        # cardinality test
        assert loss.shape == ()
        # value test
        assert (abs(grads).max() > 0).cont_all_true()

def read_tensor() -> None:
        # this is a function so that variables captured in `load` don't change
        shape_len, name_len, ftype = struct.unpack("iii", must_read(fp, 12))
        invalidInputError(0 <= shape_len <= 3, "Fail to read tensors.")
        shape = list(struct.unpack(f"{shape_len}i", must_read(fp, 4 * shape_len)))
        shape = shape[::-1]
        name = must_read(fp, name_len).decode('utf-8')
        data_type = FTYPE_TO_DATA_TYPE[ftype]

        if magic == b'ggjt':
            fp.seek((fp.tell() + 31) & -32)

        if data_type == DT_Q4_1:
            # See GPTQForLLaMaQuantizedTensor.ggml_ndarray()
            size = 24 * (shape[1] // 32) * shape[0]
        elif data_type == DT_Q4_0:
            size = 20 * (shape[1] // 32) * shape[0]
        else:
            numpy_dtype = DATA_TYPE_TO_NUMPY[data_type]
            elm_count = math.prod(shape)
            size = elm_count * numpy_dtype.itemsize
        offset = fp.tell()
        buf = mapped[offset:offset+size]
        fp.seek(size, io.SEEK_CUR)

        def load() -> Tensor:
            if isinstance(data_type, QuantizedDataType):
                ndarray = np.frombuffer(buf, dtype=np.uint32)
                return GGMLQuantizedTensor(ndarray, shape, data_type)
            else:
                return UnquantizedTensor(np.frombuffer(buf, dtype=numpy_dtype).reshape(shape))
        description = f'ggml offset={offset} type={data_type} path={path}'
        model[name] = LazyTensor(load, shape, data_type, description)

def test_training_demo(on_device, backend_fw):
    if backend_fw == "numpy":
        # numpy does not support gradients
        pytest.skip()

    ivy.set_backend(backend_fw)

    class MyModel(ivy.Module):
        def __init__(self):
            self.linear0 = ivy.Linear(3, 64)
            self.linear1 = ivy.Linear(64, 1)
            ivy.Module.__init__(self)

        def _forward(self, x):
            x = ivy.relu(self.linear0(x))
            return ivy.sigmoid(self.linear1(x))

    model = MyModel()
    optimizer = ivy.Adam(1e-4)
    x_in = ivy.array([1.0, 2.0, 3.0])
    target = ivy.array([0.0])

    def loss_fn(v):
        out = model(x_in, v=v)
        return ivy.mean((out - target) ** 2)

    for step in range(100):
        loss, grads = ivy.execute_with_gradients(loss_fn, model.v)
        model.v = optimizer.step(model.v, grads)

    ivy.previous_backend()

def loss_fn(v):
        out = model(x_in, v=v)
        return ivy.mean((out - target) ** 2)

def test_sequential_layer(
    bs_c_target, with_v, seq_v, dtype, method_flags, on_device, backend_fw
):
    with ivy.utils.backend.ContextManager(backend_fw):
        dtype = dtype[0]
        if backend_fw == "torch":
            assume("float16" not in dtype)
        if backend_fw == "paddle":
            assume(dtype != "float16")
        # smoke test
        batch_shape, channels, target = bs_c_target
        tolerance_dict = {
            "bfloat16": 1e-1,
            "float16": 1e-2,
            "float32": 1e-2,
            "float64": 1e-2,
        }
        if method_flags.as_variable[0]:
            x = _variable(
                ivy.asarray(
                    ivy.linspace(
                        ivy.zeros(batch_shape), ivy.ones(batch_shape), channels
                    ),
                    dtype=dtype,
                )
            )
        else:
            x = ivy.asarray(
                ivy.linspace(ivy.zeros(batch_shape), ivy.ones(batch_shape), channels),
                dtype=dtype,
            )
        if with_v:
            np.random.seed(0)
            wlim = (6 / (channels + channels)) ** 0.5
            v = Container(
                {
                    "submodules": {
                        "v0": {
                            "w": _variable(
                                ivy.array(
                                    np.random.uniform(
                                        -wlim, wlim, (channels, channels)
                                    ),
                                    dtype=dtype,
                                    device=on_device,
                                )
                            ),
                            "b": _variable(
                                ivy.zeros([channels], device=on_device, dtype=dtype)
                            ),
                        },
                        "v2": {
                            "w": _variable(
                                ivy.array(
                                    np.random.uniform(
                                        -wlim, wlim, (channels, channels)
                                    ),
                                    dtype=dtype,
                                    device=on_device,
                                )
                            ),
                            "b": _variable(
                                ivy.zeros([channels], device=on_device, dtype=dtype)
                            ),
                        },
                    }
                }
            )
        else:
            v = None
        if seq_v:
            seq = ivy.Sequential(
                ivy.Linear(channels, channels, device=on_device, dtype=dtype),
                ivy.Dropout(0.0, dtype=dtype),
                ivy.Linear(channels, channels, device=on_device, dtype=dtype),
                device=on_device,
                v=v if with_v else None,
                dtype=dtype,
            )
        else:
            seq = ivy.Sequential(
                ivy.Linear(
                    channels,
                    channels,
                    device=on_device,
                    v=v["submodules"]["v0"] if with_v else None,
                    dtype=dtype,
                ),
                ivy.Dropout(0.0, dtype=dtype),
                ivy.Linear(
                    channels,
                    channels,
                    device=on_device,
                    v=v["submodules"]["v2"] if with_v else None,
                    dtype=dtype,
                ),
                device=on_device,
                dtype=dtype,
            )
        ret = seq(x)
        # type test
        assert ivy.is_ivy_array(ret)
        # cardinality test
        assert ret.shape == ivy.Shape(batch_shape + [channels])
        # value test
        if not with_v:
            return
        assert np.allclose(
            ivy.to_numpy(seq(x)), np.array(target), rtol=tolerance_dict[dtype]
        )

def test_module_to_device(dummy, on_device, backend_fw):
    with ivy.utils.backend.ContextManager(backend_fw):
        model = TrainableModule(5, 5)
        model.to_device(on_device)

        def assertion(x, on_device):
            if x != on_device:
                print(f"{x} is not equal to {on_device}")
                raise AssertionError

        def model_assert(mod, on_device):
            for obj in mod.v.values():
                if isinstance(obj, ivy.Module):
                    return model_assert(obj, on_device)
                if isinstance(obj, (ivy.Container, dict)):
                    for item2 in obj.values():
                        assertion(item2.device, on_device)

                else:
                    assertion(obj.device, on_device)
            if getattr(mod, "buffers", None):
                for obj in mod.buffers.values():
                    if isinstance(obj, (ivy.Container, dict)):
                        ivy.nested_map(lambda x: assertion(x.device, on_device), obj)
                    else:
                        assertion(obj.device, on_device)

        model_assert(model, on_device)

def add_module(self, name: str, module: Optional["Model"]) -> None:
        if not isinstance(module, (Model, Layer, keras.Model,  keras.layers.Layer)) and module is not None:
            raise TypeError(f"{type(module)} is not a Module subclass")
        elif not isinstance(name, str):
            raise TypeError(f"module name should be a string. Got {type(name)}")
        elif hasattr(self, name) and name not in self._modules:
            raise KeyError(f"attribute '{name}' already exists")
        elif "." in name:
            raise KeyError(f'module name can\'t contain ".", got: {name}')
        elif name == "":
            raise KeyError('module name can\'t be empty string ""')

        self._modules[name] = module

        super().__setattr__(name, module)

def get_submodule(self, target: str) -> "Model":
        if target == "":
            return self

        atoms: List[str] = target.split(".")
        mod: Model = self

        for item in atoms:
            if not hasattr(mod, item):
                raise AttributeError(
                    mod._get_name() + " has no attribute `" + item + "`"
                )

            mod = getattr(mod, item)

            if not isinstance(mod, (Model, Layer, keras.Model,  keras.layers.Layer)):
                raise TypeError("`" + item + "` is not a Module")

        return mod

def get_attention(model, model_type, tokenizer, sentence_a, sentence_b=None, include_queries_and_keys=False):
    """Compute representation of attention to pass to the d3 visualization

    Args:
        model: pytorch-transformers model
        model_type: type of model. Valid values 'bert', 'gpt2', 'xlnet', 'roberta'
        tokenizer: pytorch-transformers tokenizer
        sentence_a: Sentence A string
        sentence_b: Sentence B string
        include_queries_and_keys: Indicates whether to include queries/keys in results

    Returns:
      Dictionary of attn representations with the structure:
      {
        'all': All attention (source = AB, target = AB)
        'aa': Sentence A self-attention (source = A, target = A) (if sentence_b is not None)
        'bb': Sentence B self-attention (source = B, target = B) (if sentence_b is not None)
        'ab': Sentence A -> Sentence B attention (source = A, target = B) (if sentence_b is not None)
        'ba': Sentence B -> Sentence A attention (source = B, target = A) (if sentence_b is not None)
      }
      where each value is a dictionary:
      {
        'left_text': list of source tokens, to be displayed on the left of the vis
        'right_text': list of target tokens, to be displayed on the right of the vis
        'attn': list of attention matrices, one for each layer. Each has shape [num_heads, source_seq_len, target_seq_len]
        'queries' (optional): list of query vector arrays, one for each layer. Each has shape (num_heads, source_seq_len, vector_size)
        'keys' (optional): list of key vector arrays, one for each layer. Each has shape (num_heads, target_seq_len, vector_size)
      }
    """

    if model_type not in ('bert', 'gpt2', 'xlnet', 'roberta'):
        raise ValueError("Invalid model type:", model_type)
    if not sentence_a:
        raise ValueError("Sentence A is required")
    is_sentence_pair = bool(sentence_b)
    if is_sentence_pair and model_type not in ('bert', 'roberta', 'xlnet'):
        raise ValueError(f'Model {model_type} does not support sentence pairs')
    if is_sentence_pair and model_type == 'xlnet':
        raise NotImplementedError("Sentence-pair inputs for XLNet not currently supported.")

    # Prepare inputs to model
    tokens_a = None
    tokens_b = None
    token_type_ids = None
    if not is_sentence_pair:  # Single sentence
        if model_type in ('bert', 'roberta'):
            tokens_a = [tokenizer.cls_token] + tokenizer.tokenize(sentence_a) + [tokenizer.sep_token]
        elif model_type == 'xlnet':
            tokens_a = tokenizer.tokenize(sentence_a) + [tokenizer.sep_token] + [tokenizer.cls_token]
        else:
            tokens_a = tokenizer.tokenize(sentence_a)
    else:
        if model_type == 'bert':
            tokens_a = [tokenizer.cls_token] + tokenizer.tokenize(sentence_a) + [tokenizer.sep_token]
            tokens_b = tokenizer.tokenize(sentence_b) + [tokenizer.sep_token]
            token_type_ids = torch.LongTensor([[0] * len(tokens_a) + [1] * len(tokens_b)])
        elif model_type == 'roberta':
            tokens_a = [tokenizer.cls_token] + tokenizer.tokenize(sentence_a) + [tokenizer.sep_token]
            tokens_b = [tokenizer.sep_token] + tokenizer.tokenize(sentence_b) + [tokenizer.sep_token]
            # Roberta doesn't use token type embeddings per https://github.com/huggingface/pytorch-transformers/blob/master/pytorch_transformers/convert_roberta_checkpoint_to_pytorch.py
        else:
            tokens_b = tokenizer.tokenize(sentence_b)

    token_ids = tokenizer.convert_tokens_to_ids(tokens_a + (tokens_b if tokens_b else []))
    tokens_tensor = torch.tensor(token_ids).unsqueeze(0)

    # Call model to get attention data
    model.eval()
    if token_type_ids is not None:
        output = model(tokens_tensor, token_type_ids=token_type_ids)
    else:
        output = model(tokens_tensor)
    attn_data_list = output[-1]

    # Populate map with attn data and, optionally, query, key data
    attn_dict = defaultdict(list)
    if include_queries_and_keys:
        queries_dict = defaultdict(list)
        keys_dict = defaultdict(list)

    if is_sentence_pair:
        slice_a = slice(0, len(tokens_a))  # Positions corresponding to sentence A in input
        slice_b = slice(len(tokens_a), len(tokens_a) + len(tokens_b))  # Position corresponding to sentence B in input
    for layer, attn_data in enumerate(attn_data_list):
        # Process attention
        attn = attn_data['attn'][0]  # assume batch_size=1; shape = [num_heads, source_seq_len, target_seq_len]
        attn_dict['all'].append(attn.tolist())
        if is_sentence_pair:
            attn_dict['aa'].append(
                attn[:, slice_a, slice_a].tolist())  # Append A->A attention for layer, across all heads
            attn_dict['bb'].append(
                attn[:, slice_b, slice_b].tolist())  # Append B->B attention for layer, across all heads
            attn_dict['ab'].append(
                attn[:, slice_a, slice_b].tolist())  # Append A->B attention for layer, across all heads
            attn_dict['ba'].append(
                attn[:, slice_b, slice_a].tolist())  # Append B->A attention for layer, across all heads
        # Process queries and keys
        if include_queries_and_keys:
            queries = attn_data['queries'][0]  # assume batch_size=1; shape = [num_heads, seq_len, vector_size]
            keys = attn_data['keys'][0]  # assume batch_size=1; shape = [num_heads, seq_len, vector_size]
            queries_dict['all'].append(queries.tolist())
            keys_dict['all'].append(keys.tolist())
            if is_sentence_pair:
                queries_dict['a'].append(queries[:, slice_a, :].tolist())
                keys_dict['a'].append(keys[:, slice_a, :].tolist())
                queries_dict['b'].append(queries[:, slice_b, :].tolist())
                keys_dict['b'].append(keys[:, slice_b, :].tolist())

    tokens_a = format_special_chars(tokens_a)
    if tokens_b:
        tokens_b = format_special_chars(tokens_b)
    if model_type != 'gpt2':
        tokens_a = format_delimiters(tokens_a, tokenizer)
        if tokens_b:
            tokens_b = format_delimiters(tokens_b, tokenizer)

    results = {
        'all': {
            'attn': attn_dict['all'],
            'left_text': tokens_a + (tokens_b if tokens_b else []),
            'right_text': tokens_a + (tokens_b if tokens_b else [])
        }
    }
    if is_sentence_pair:
        results.update({
            'aa': {
                'attn': attn_dict['aa'],
                'left_text': tokens_a,
                'right_text': tokens_a
            },
            'bb': {
                'attn': attn_dict['bb'],
                'left_text': tokens_b,
                'right_text': tokens_b
            },
            'ab': {
                'attn': attn_dict['ab'],
                'left_text': tokens_a,
                'right_text': tokens_b
            },
            'ba': {
                'attn': attn_dict['ba'],
                'left_text': tokens_b,
                'right_text': tokens_a
            }
        })
    if include_queries_and_keys:
        results['all'].update({
            'queries': queries_dict['all'],
            'keys': keys_dict['all'],
        })
        if is_sentence_pair:
            results['aa'].update({
                'queries': queries_dict['a'],
                'keys': keys_dict['a'],
            })
            results['bb'].update({
                'queries': queries_dict['b'],
                'keys': keys_dict['b'],
            })
            results['ab'].update({
                'queries': queries_dict['a'],
                'keys': keys_dict['b'],
            })
            results['ba'].update({
                'queries': queries_dict['b'],
                'keys': keys_dict['a'],
            })
    return results

def format_attention(attention, layers=None, heads=None):
    if layers:
        attention = [attention[layer_index] for layer_index in layers]
    squeezed = []
    for layer_attention in attention:
        # 1 x num_heads x seq_len x seq_len
        if len(layer_attention.shape) != 4:
            raise ValueError("The attention tensor does not have the correct number of dimensions. Make sure you set "
                             "output_attentions=True when initializing your model.")
        layer_attention = layer_attention.squeeze(0)
        if heads:
            layer_attention = layer_attention[heads]
        squeezed.append(layer_attention)
    # num_layers x num_heads x seq_len x seq_len
    return torch.stack(squeezed)

def _load_from_state_dict(
        self, state_dict, prefix, strict, missing_keys, unexpected_keys, error_msgs
    ):
        def _retrive_layer(model, key):
            if len(key.split(".")) == 1:
                return model, key

            module_path, weight_name = key.rsplit(".", 1)

            # Retrieve the layer using the module path
            layer = model
            for attr in module_path.split("."):
                layer = getattr(layer, attr)

            return layer, weight_name

        persistent_buffers = {k: v for k, v in self._buffers.items()}
        local_name_params = itertools.chain(
            self._parameters.items(), persistent_buffers.items()
        )
        local_state = {k: v for k, v in local_name_params if v is not None}

        for name, param in local_state.items():
            key = prefix + name
            if key in state_dict:
                input_param = state_dict[key]
                if not isinstance(input_param, tf.Tensor):
                    error_msgs.append(
                        f'While copying the parameter named "{key}", '
                        "expected ArrayLike object from checkpoint but "
                        f"received {type(input_param)}"
                    )
                    continue

                if not isinstance(input_param, KerasVariable):
                    input_param = KerasVariable(input_param)

                layer, weight_name = _retrive_layer(self, name)
                try:
                    setattr(layer, weight_name, input_param)
                except Exception as ex:
                    error_msgs.append(
                        f'While copying the parameter named "{key}", '
                        f"whose dimensions in the model are {param.shape} and "
                        f"whose dimensions in the checkpoint are {input_param.shape}, "
                        f"an exception occurred : {ex.args}."
                    )
            elif strict:
                missing_keys.append(key)

        if strict:
            for key in state_dict.keys():
                if key.startswith(prefix):
                    input_name = key[len(prefix) :].split(".", 1)
                    if len(input_name) > 1:
                        if input_name[0] not in self._modules:
                            unexpected_keys.append(key)
                    elif input_name[0] not in local_state:
                        unexpected_keys.append(key)

def load_tf_weights_in_bert(model, config, tf_checkpoint_path):
    """ Load tf checkpoints in a pytorch model.
    """
    try:
        import re
        import numpy as np
        import tensorflow as tf
    except ImportError:
        logger.error("Loading a TensorFlow model in PyTorch, requires TensorFlow to be installed. Please see "
            "https://www.tensorflow.org/install/ for installation instructions.")
        raise
    tf_path = os.path.abspath(tf_checkpoint_path)
    logger.info("Converting TensorFlow checkpoint from {}".format(tf_path))
    # Load weights from TF model
    init_vars = tf.train.list_variables(tf_path)
    names = []
    arrays = []
    for name, shape in init_vars:
        logger.info("Loading TF weight {} with shape {}".format(name, shape))
        array = tf.train.load_variable(tf_path, name)
        names.append(name)
        arrays.append(array)

    for name, array in zip(names, arrays):
        name = name.split('/')
        # adam_v and adam_m are variables used in AdamWeightDecayOptimizer to calculated m and v
        # which are not required for using pretrained model
        if any(n in ["adam_v", "adam_m", "global_step"] for n in name):
            logger.info("Skipping {}".format("/".join(name)))
            continue
        pointer = model
        for m_name in name:
            if re.fullmatch(r'[A-Za-z]+_\d+', m_name):
                l = re.split(r'_(\d+)', m_name)
            else:
                l = [m_name]
            if l[0] == 'kernel' or l[0] == 'gamma':
                pointer = getattr(pointer, 'weight')
            elif l[0] == 'output_bias' or l[0] == 'beta':
                pointer = getattr(pointer, 'bias')
            elif l[0] == 'output_weights':
                pointer = getattr(pointer, 'weight')
            elif l[0] == 'squad':
                pointer = getattr(pointer, 'classifier')
            else:
                try:
                    pointer = getattr(pointer, l[0])
                except AttributeError:
                    logger.info("Skipping {}".format("/".join(name)))
                    continue
            if len(l) >= 2:
                num = int(l[1])
                pointer = pointer[num]
        if m_name[-11:] == '_embeddings':
            pointer = getattr(pointer, 'weight')
        elif m_name == 'kernel':
            array = np.transpose(array)
        try:
            assert pointer.shape == array.shape
        except AssertionError as e:
            e.args += (pointer.shape, array.shape)
            raise
        logger.info("Initialize PyTorch weight {}".format(name))
        pointer.data = torch.from_numpy(array)
    return model

def restore_image(self,
                      img_path: str,
                      model_name: Optional[str] = None,
                      scale: int = 1,
                      half_precision: Optional[bool] = None,
                      overwrite: bool = True):
        model_config = {
            "model_name": self.model_config["model_name"],
            "scale": scale,
            "half_precision": half_precision
        }
        half_precision = True if self.device == "cuda" else False

        if self.model is None or self.model_config != model_config:
            self.load_model(
                model_name=self.default_model if model_name is None else model_name,
                scale=scale,
                half_precision=half_precision
            )

        try:
            with torch.autocast(device_type=self.device, enabled=(self.device == "cuda")):
                output, img_mode = self.model.enhance(img_path, outscale=scale)
            if img_mode == "RGB":
                output = cv2.cvtColor(output, cv2.COLOR_RGB2BGR)

            if overwrite:
                output_path = img_path
            else:
                output_path = get_auto_incremental_file_path(self.output_dir, extension="png")

            output_path = save_image(output, output_path=output_path)
            return output_path
        except Exception as e:
            raise

def get_lm_corpus(datadir, dataset):
    fn = os.path.join(datadir, 'cache.pt')
    fn_pickle = os.path.join(datadir, 'cache.pkl')
    if os.path.exists(fn):
        logger.info('Loading cached dataset...')
        corpus = torch.load(fn_pickle)
    elif os.path.exists(fn):
        logger.info('Loading cached dataset from pickle...')
        with open(fn, "rb") as fp:
            corpus = pickle.load(fp)
    else:
        logger.info('Producing dataset {}...'.format(dataset))
        kwargs = {}
        if dataset in ['wt103', 'wt2']:
            kwargs['special'] = ['<eos>']
            kwargs['lower_case'] = False
        elif dataset == 'ptb':
            kwargs['special'] = ['<eos>']
            kwargs['lower_case'] = True
        elif dataset == 'lm1b':
            kwargs['special'] = []
            kwargs['lower_case'] = False
            kwargs['vocab_file'] = os.path.join(datadir, '1b_word_vocab.txt')
        elif dataset in ['enwik8', 'text8']:
            pass

        corpus = TransfoXLCorpus(datadir, dataset, **kwargs)
        torch.save(corpus, fn)

    return corpus

def create_video_from_numpy_list(frame_list: List[np.ndarray],
                                 frame_rate: Optional[int] = None,
                                 sound_path: Optional[str] = None,
                                 output_dir: Optional[str] = None
                                 ):
    if output_dir is None:
        output_dir = OUTPUTS_VIDEOS_DIR
    os.makedirs(output_dir, exist_ok=True)
    output_path = get_auto_incremental_file_path(output_dir, "mp4")

    if frame_rate is None:
        frame_rate = 25

    if sound_path is None:
        temp_sound = os.path.join(TEMP_VIDEO_FRAMES_DIR, "sound.mp3")
        if os.path.exists(temp_sound):
            sound_path = temp_sound

    height, width, layers = frame_list[0].shape
    fourcc = cv2.VideoWriter.fourcc(*'mp4v')

    out = cv2.VideoWriter(output_path, fourcc, frame_rate, (width, height))

    for frame in frame_list:
        out.write(cv2.cvtColor(frame, cv2.COLOR_RGB2BGR))

    out.release()

def _get_spark_dataset_hash(dataset: DataFrame) -> str:
    """Get pyspark dataset hash value."""
    shape = ((dataset.count(), len(dataset.columns)))
    row_count = shape[0]
    other_info = str(shape) + "_pyspark"
    if row_count > 4000:
        dataset = dataset.limit(4000)
    dataset_pd = dataset.toPandas()
    hash_bytes = pd.util.hash_pandas_object(dataset_pd).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def _get_modin_dataset_hash(dataset: DataFrame) -> str:
    """Get modin dataset hash value."""
    import modin.pandas as mpd
    row_count = dataset.shape[0]
    other_info = str(dataset.shape) + "_modin"
    if row_count > 4000:
        dataset = mpd.concat([dataset[:2000], dataset[-2000:]])
    dataset = dataset._to_pandas()
    hash_bytes = pd.util.hash_pandas_object(dataset).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def _get_pl_dataset_hash(dataset: DataFrame) -> str:
    """Get polars dataset hash value."""
    import polars as pl
    row_count = dataset.shape[0]
    other_info = str(dataset.shape) + "_polars"
    if row_count > 4000:
        dataset = pl.concat([dataset[:2000], dataset[-2000:]])
    hash_bytes = dataset.hash_rows().to_numpy().tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def _get_pd_dataset_hash(dataset: DataFrame) -> str:
    """Get pandas dataset hash value."""
    row_count = dataset.shape[0]
    other_info = str(dataset.shape) + "_pandas"
    if row_count > 4000:
        dataset = pd.concat([dataset[:2000], dataset[-2000:]])
    hash_bytes = pd.util.hash_pandas_object(dataset).values.tobytes() + other_info.encode()
    return hashlib.md5(hash_bytes).hexdigest()

def get_dataset_hash(dataset: Union[DataFrame, Connector, str]) -> str:
    """Just a less accurate way to get different dataset hash values."""
    _, dataset_type = _get_data_parser(dataset)

    if dataset_type == "polars":
        return _get_pl_dataset_hash(dataset)

    if dataset_type == "pandas":
        return _get_pd_dataset_hash(dataset)

    if dataset_type == "modin":
        return _get_modin_dataset_hash(dataset)

    if dataset_type == "pyspark":
        return _get_spark_dataset_hash(dataset)

    if dataset_type == "connector":
        return hashlib.md5("_".join([dataset.url, dataset.view_sql, dataset_type]).encode()).hexdigest()

    if dataset_type == "cloud_dataset":
        return hashlib.md5("_".join([dataset, dataset_type]).encode()).hexdigest()

def get_model():
    inputs = keras.Input(shape=(128,))
    outputs = layers.Dense(1)(inputs)
    return keras.Model(inputs, outputs)

def compute_loss_and_updates(
    trainable_variables, non_trainable_variables, metric_variables, x, y
):
    y_pred, non_trainable_variables, losses = model.stateless_call(
        trainable_variables, non_trainable_variables, x, return_losses=True
    )
    loss = loss_fn(y, y_pred)
    if losses:
        loss += jax.numpy.sum(losses)
    metric_variables = train_acc_metric.stateless_update_state(
        metric_variables, y, y_pred
    )
    return loss, non_trainable_variables, metric_variables

