def _update_model(self):
        _logger.info('Updating model on %d samples', len(self.x))
        x_arr = []
        for x in self.x:
            x_arr.append([x[k] for k in sorted(x.keys())])
        try:
            self.model.train(np.array(x_arr), np.array(self.y), do_optimize=True)
        except np.linalg.LinAlgError as e:
            warnings.warn(f'numpy linalg error encountered in DNGO model training: {e}')
        self._model_initialized = True

def import_data(self, data):  # for resuming experiment
        if isinstance(data, str):
            data = nni.load(data)
        for trial in data:
            if isinstance(trial, str):
                trial = nni.load(trial)
            param = format_parameters(trial['parameter'], self.space)
            loss = trial['value']
            if isinstance(loss, dict) and 'default' in loss:
                loss = loss['default']
            if self.optimize_mode is OptimizeMode.Maximize:
                loss = -loss
            for key, value in param.items():
                self._history[key].append(Record(value, loss))
                self.dedup.add_history(param)
        _logger.info(f'Replayed {len(data)} FINISHED trials')

def _trace(self, model, dummy_input):
        training = model.training
        model.eval()
        kw_args = {}
        if torch.__version__ >= '1.6.0':
            # only pytorch with version greater than 1.6.0 has the strict option
            kw_args['strict'] = False
        try:
            import pytorch_lightning as pl
        except ImportError:
            is_lightning_module = False
        else:
            if isinstance(model, pl.LightningModule):
                is_lightning_module = True
            else:
                is_lightning_module = False
        if is_lightning_module:
            self.trace = model.to_torchscript(method="trace", example_inputs=dummy_input, **kw_args)
        else:
            self.trace = torch.jit.trace(model, dummy_input, **kw_args)
        torch._C._jit_pass_inline(self.trace.graph)
        model.train(training)

def generate_masks(self) -> Dict[str, Dict[str, torch.Tensor]]:
        data = self._collect_data()
        metrics = self._calculate_metrics(data)
        return self._generate_sparsity(metrics)

def _calculate_metrics(self, data: Dict[str, Dict[str, torch.Tensor]]) -> Dict[str, Dict[str, torch.Tensor]]:
        metrics = defaultdict(dict)
        for module_name, td in data.items():
            for target_name, target_data in td.items():
                if self._target_spaces[module_name][target_name].sparse_threshold is not None:
                    metrics[module_name][target_name] = target_data.sigmoid()
                else:
                    metrics[module_name][target_name] = target_data
        return metrics

def fpgm_metrics(p: str | int, data: _DATA, target_spaces: _PRUNING_TARGET_SPACES) -> _METRICS:
    def reduce_func(t: torch.Tensor) -> torch.Tensor:
        reshape_data = t.reshape(-1, t.shape[-1])
        metric = torch.zeros(reshape_data.shape[0]).type_as(reshape_data)
        for i in range(reshape_data.shape[0]):
            metric[i] = (reshape_data - reshape_data[i]).norm(p=p, dim=-1).sum()  # type: ignore
        return metric.reshape(t.shape[:-1])

    metrics = defaultdict(dict)
    for module_name, module_data in data.items():
        for target_name, target_data in module_data.items():
            target_space = target_spaces[module_name][target_name]
            assert target_space._scaler is not None, 'FPGM metric do not support finegrained sparse pattern.'
            metrics[module_name][target_name] = target_space._scaler.shrink(target_data, reduce_func, keepdim=True)
    return metrics

def register_wrappers(model: torch.nn.Module, config_list: List[Dict[str, Any]],
                      mode: Literal['pruning', 'quantization', 'distillation'],
                      existed_wrappers: Dict[str, ModuleWrapper] | None = None,
                      ) -> Tuple[Dict[str, ModuleWrapper], Dict[str, Dict[str, TargetSpace]]]:
    assert mode in ['pruning', 'quantization', 'distillation']

    configured_target_spaces = defaultdict(dict)
    existed_wrappers = existed_wrappers if existed_wrappers else {}
    module_wrappers = {k: v for k, v in existed_wrappers.items()}
    identity_module_set = set()
    module_set = set()
    for config in config_list:
        fuse_module_names: List[Tuple[str]]
        modules, public_config, fuse_module_names = select_modules_by_config(model, config)
        if len(fuse_module_names) > 0:
            validate_fused_modules_config(fuse_module_names, model, public_config)
        for module_name, module in modules.items():
            module_set.add(module_name)
            fused_modules_pair: Tuple[str] = get_fused_module_list(module_name, mode, fuse_module_names)
            if len(fused_modules_pair) > 0:
                fuse_module_names.remove(fused_modules_pair)
            old_wrapper = module_wrappers.get(module_name, None)
            if len(fused_modules_pair) > 0: #fusion model
                identity_module_set.update(fused_modules_pair[1:])
            wrapper, target_spaces = create_module_wrapper(model, module, module_name, mode, public_config, \
                                                           old_wrapper, list(fused_modules_pair))
            module_wrappers[module_name] = wrapper
            configured_target_spaces[module_name].update(target_spaces)
        if len(fuse_module_names) > 0:
            raise ValueError(f'{fuse_module_names} can\'t be fused with {modules.keys()}')
    if module_set.intersection(identity_module_set):
        raise ValueError(f"Don't provide quantization settings for identity modules:{module_set.intersection(identity_module_set)}")
    for module_name, module in model.named_modules():
        if module_name in identity_module_set:
            if module_name in module_wrappers and not isinstance(module_wrappers[module_name], IdentityModuleWrapper):
                warn_msg = f'Wrapper of {module_name} is wrapped, no need to wrap it because of module fusion.'
                raise ValueError(warn_msg)
            module_wrappers[module_name] = IdentityModuleWrapper(module, module_name, None, None)
            identity_module_set.remove(module_name)

    assert len(identity_module_set) == 0, f"{identity_module_set} do not exist in the model"

    return module_wrappers, configured_target_spaces

def _generate_dependency_sparsity(metrics: _METRICS, target_spaces: _PRUNING_TARGET_SPACES) -> _MASKS:
    groups: Dict[str, List[Tuple[str, str, PruningTargetSpace]]] = defaultdict(list)
    for module_name, ts in target_spaces.items():
        for target_name, target_space in ts.items():
            groups[target_space.dependency_group_id].append((module_name, target_name, target_space))  # type: ignore

    masks = defaultdict(dict)
    for _, group in groups.items():
        block_numbers = [1]
        group_sparsity_ratio = None
        filtered_metrics = defaultdict(dict)

        for module_name, target_name, target_space in group:
            assert target_space.internal_metric_block is None or isinstance(target_space.internal_metric_block, int)
            block_numbers.append(target_space.internal_metric_block if target_space.internal_metric_block else 1)
            if target_space.sparse_ratio is not None:
                if group_sparsity_ratio is None:
                    group_sparsity_ratio = target_space.sparse_ratio
                else:
                    assert group_sparsity_ratio == target_space.sparse_ratio
            filtered_metrics[module_name][target_name] = metrics[module_name][target_name]
        block_number = reduce(numpy.lcm, block_numbers)
        assert group_sparsity_ratio is not None
        group_metric = _metric_fuse(filtered_metrics)
        group_mask = _ratio_mask(group_metric, group_sparsity_ratio, view_size=[block_number, -1])

        for module_name, target_name, _ in group:
            masks[module_name][target_name] = group_mask.clone()

    return masks

def _global_threshold_generate(metrics: _METRICS,
                               group: List[Tuple[str, str, PruningTargetSpace]],
                               sparse_number: int) -> float:
    buffer = []
    buffer_elem = 0
    for module_name, target_name, target_space in group:
        metric = metrics[module_name][target_name]
        grain_size = target_space.target.numel() // metric.numel()  # type: ignore
        for m in metric.cpu().detach().view(-1):
            if buffer_elem <= sparse_number:
                heapq.heappush(buffer, (-m.item(), grain_size))
                buffer_elem += grain_size
            else:
                _, previous_grain_size = heapq.heappushpop(buffer, (-m.item(), grain_size))
                buffer_elem += grain_size - previous_grain_size
    return -heapq.heappop(buffer)[0]

def _metric_fuse(metrics: _METRICS) -> torch.Tensor:
    # mean all metric value
    fused_metric = None
    count = 0
    for _, module_metrics in metrics.items():
        for _, target_metric in module_metrics.items():
            if fused_metric is not None:
                fused_metric += target_metric
            else:
                fused_metric = target_metric.clone()
            count += 1
    assert fused_metric is not None
    return fused_metric / count

def reset_ddp_model(model: torch.nn.parallel.DistributedDataParallel, ddp_params: Dict):
    assert isinstance(model, torch.nn.parallel.DistributedDataParallel)
    module = model.module
    return torch.nn.parallel.DistributedDataParallel(module=module, **ddp_params)

def patch_loss(self, patch: Callable[[Tensor, Any], Tensor]):
        old_compute_loss = self.trainer.compute_loss

        def patched_compute_loss(_, model: Any, inputs: Any, return_outputs: bool = False):
            result = old_compute_loss(model, inputs, return_outputs)
            if return_outputs:
                return patch(result[0], inputs), result[1]
            else:
                return patch(result, inputs)

        self.trainer.compute_loss = types.MethodType(patched_compute_loss, self.trainer)

def custom_on_train_begin(_, args: TrainingArguments, state: TrainerState, control: TrainerControl, **kwargs):
            optimizer = self.trainer.deepspeed if hasattr(self.trainer, "deepspeed") else self.trainer.callback_handler.optimizer

            assert optimizer is not None
            old_step = optimizer.step

            def patched_step(_, *args, **kwargs):
                for task in before_step_tasks:
                    task()
                # call origin optimizer step method
                output = old_step(*args, **kwargs)
                for task in after_step_tasks:
                    task()
                return output

            optimizer.step = types.MethodType(patched_step, optimizer)

def fix_mask(self):
        """
        Fix the mask conflict before the mask inference for the layers that
        has shape dependencies. This function should be called before the
        mask inference of the 'speedup' module. Only structured pruning masks
        are supported.
        """
        if self.conv_prune_dim == 0:
            channel_depen = ChannelDependency(
                self.model, self.dummy_input, self.traced, self.channel_prune_type)

        else:
            channel_depen = InputChannelDependency(
                self.model, self.dummy_input, self.traced)
        depen_sets = channel_depen.dependency_sets
        sum_idx = (1, 2, 3) if self.conv_prune_dim == 0 else (0, 2, 3)

        (_tmp_name, _tmp_tensor) = list(self.masks.items())[0]
        device = list(_tmp_tensor.values())[0].device

        for dset in depen_sets:
            if len(dset) <= 1:
                continue
            # channel_masks is a list, each element is None or a vector, for example:
            # [[0, 1, 1, 0, 0], [0, 0, 1, 1, 0], None], None means no channel
            # is pruned.
            channel_masks = []
            fine_grained = False
            for name in dset:
                if name in self.masks and 'weight' in self.masks[name]:
                    m = get_nested_attr(self.model, name)
                    assert m is not None
                    mask = self.masks[name]['weight']
                    if type(m).__name__ == 'Conv2d':
                        channel_mask = (mask.abs().sum(sum_idx) != 0).int()
                        if self.conv_prune_dim == 1:
                            channel_mask = channel_mask.repeat(m.groups)
                        channel_masks.append(channel_mask)
                        if (channel_mask.sum() * (mask.numel() / mask.shape[self.conv_prune_dim])).item() != (mask > 0).sum().item():
                            fine_grained = True
                    elif type(m).__name__ == 'Linear':
                        if self.conv_prune_dim == 1:
                            channel_masks.append(
                                (mask.abs().sum(0) != 0).int())
                        else:
                            channel_masks.append(
                                (mask.abs().sum(1) != 0).int())
                    elif type(m).__name__ == 'Embedding':
                        if self.conv_prune_dim == 0:
                            channel_masks.append(
                                (mask.abs().sum(0) != 0).int())
                    elif type(m).__name__ == 'BatchNorm2d':
                        channel_masks.append(mask.int())
                    elif type(m).__name__ == 'ConvTranspose2d':
                        # convtranspose have difference memory layout, so that we need create
                        # a tmp_sum_idx for conv_transpose
                        tmp_sum_idx = (
                            0, 2, 3) if self.conv_prune_dim == 0 else (1, 2, 3)
                        channel_mask = (mask.abs().sum(tmp_sum_idx) != 0).int()
                        if self.conv_prune_dim == 0:
                            channel_mask = channel_mask.repeat(m.groups)
                        channel_masks.append(channel_mask)
                        if (channel_mask.sum() * (mask.numel() / mask.shape[1 - self.conv_prune_dim])).item() != (mask > 0).sum().item():
                            fine_grained = True
                    else:
                        raise RuntimeError(
                            f'unsupported module type: {type(m).__name__}')
                else:
                    # no mask means not pruned, equivlent to full masks
                    channel_masks.append(None)
            if fine_grained:
                _logger.info("Fine-grianed mask detected")
            if all(x is None for x in channel_masks):
                continue
            num_channels_list = [len(x)
                                 for x in channel_masks if x is not None]
            # number of channels in same set should be identical
            assert len(set(num_channels_list)) == 1
            num_channels = num_channels_list[0]

            for i, dim_mask in enumerate(channel_masks):
                if dim_mask is None:
                    channel_masks[i] = torch.ones(
                        num_channels).int().to(device)

            # merge masks with 'or'
            merged_channel_mask = channel_masks[0].clone()
            for i in range(1, len(channel_masks)):
                merged_channel_mask = (
                    (merged_channel_mask + channel_masks[i]) != 0).int()

            merged_index = torch.nonzero(merged_channel_mask, as_tuple=True)[0]

            for name in dset:
                if name not in self.masks or 'weight' not in self.masks[name]:
                    assert all(merged_channel_mask)
                    continue
                orig_mask = self.masks[name]['weight']
                m = get_nested_attr(self.model, name)
                new_mask = torch.zeros_like(orig_mask)
                if type(m).__name__ == 'Conv2d':
                    if self.conv_prune_dim == 0:
                        new_mask[merged_index, :, :, :] = 1.
                    else:
                        new_mask[:, torch.nonzero(merged_channel_mask[:new_mask.shape[1]], as_tuple=True)[0], :, :] = 1.
                elif type(m).__name__ == 'Linear':
                    if self.conv_prune_dim == 0:
                        new_mask[merged_index, :] = 1.
                    elif self.conv_prune_dim == 1:
                        new_mask[:, merged_index] = 1.
                elif type(m).__name__ == 'Embedding':
                    if self.conv_prune_dim == 0:
                        new_mask[:, merged_index] = 1.
                elif type(m).__name__ == 'BatchNorm2d':
                    new_mask = merged_channel_mask.type_as(orig_mask)
                else:
                    raise RuntimeError(
                        f'unsupported module type: {type(m).__name__}')
                self.masks[name]['weight'] = new_mask
                if 'bias' in self.masks[name] and self.masks[name]['bias'] is not None:
                    if self.conv_prune_dim == 0:
                        self.masks[name]['bias'] = merged_channel_mask.type_as(
                            self.masks[name]['bias'])

        return self.masks

def __init__(self, model: torch.nn.Module, parser: HuggingfaceModelParser | None = None):
        self.parser = parser_factory(model) if parser is None else parser
        if self.parser is None:
            err_msg = f'Can not get the model parser of {type(model)}'
            raise RuntimeError(err_msg)

def patch_loss(self, patch: Callable[[Tensor, Any], Tensor]):
        assert isinstance(self.model, pl.LightningModule)
        old_training_step = self.model.training_step

        def patched_training_step(_, *args, **kwargs):
            output = old_training_step(*args, **kwargs)
            batch = args[0] if len(args) > 0 else kwargs['batch']
            if isinstance(output, Tensor):
                output = patch(output, batch)
            else:
                output['loss'] = patch(output['loss'], batch)
            return output

        self.model.training_step = types.MethodType(patched_training_step, self.model)

def _execute(self, model: ExecutableModelSpace) -> Any:
        """Execute the model with the sample."""

        from .space import BenchmarkModelSpace
        if not isinstance(model, BenchmarkModelSpace):
            warnings.warn('It would be better to use BenchmarkModelSpace for benchmarking to avoid '
                          'unnecessary overhead and silent mistakes.')
        if model.sample is None:
            raise ValueError('Model can not be evaluted because it has not been sampled yet.')

        return self.evaluate(model.sample)

def get_num_heads(cls, module_name: str, model: Module) -> int:
        if cls.is_attention(module_name, include_output=True) or cls.is_attention_layer(module_name):
            for pattern in cls.ATTENTION:
                match = re.search(pattern, module_name)
                if match:
                    attention_module_name = module_name[0: match.span()[1]]
                    module = get_nested_attr(model, attention_module_name)
                    if hasattr(module, 'self') and hasattr(getattr(module, 'self'), 'num_attention_heads'):
                        num_heads = module.self.num_attention_heads
                    elif hasattr(module, 'num_heads'):
                        num_heads = module.num_heads
                    elif hasattr(module, 'n_heads'):
                        num_heads = module.n_heads
                    else:
                        warn_msg = f'Can not get the heads number of attention layer : `{attention_module_name}`.'
                        _logger.warning(warn_msg)
                        num_heads = 0
                    return num_heads
            return 0
        else:
            warn_msg = f'The layer `{module_name}` might not an (Q|K|V) attention layer.'
            _logger.warning(warn_msg)
            return 0

def fit(self, model):
        warnings.warn('`fit` is deprecated, please use `evaluate`.', DeprecationWarning)
        return self.evaluate(model)

def validation_step(self, batch, batch_idx):
        x, y = batch
        y_hat = self(x)

        if self.export_onnx is not None:
            self.export_onnx.parent.mkdir(exist_ok=True)
            try:
                self.to_onnx(self.export_onnx, x, export_params=True)
            except RuntimeError as e:
                warnings.warn(f'ONNX conversion failed. As a result, you might not be able to use visualization. Error message: {e}')
            self.export_onnx = None

        self.log('val_loss', self.criterion(y_hat, y), prog_bar=True)
        for name, metric in self.metrics.items():
            self.log('val_' + name, metric(y_hat, y), prog_bar=True)

def _get_result_for_report(self):
        stage = 'val'
        if not self.trainer.val_dataloaders:
            _logger.debug('No validation dataloader. Use results on training set instead.')
            stage = 'train'

        if len(self.metrics) == 1:
            metric_name = next(iter(self.metrics))
            return self.trainer.callback_metrics[f'{stage}_{metric_name}'].item()
        else:
            warnings.warn('Multiple metrics without "default" is not supported by current framework.')
            return {name: self.trainer.callback_metrics[f'{stage}_{name}'].item() for name in self.metrics}

def _optimizer_add_param_group(self, model: Union[torch.nn.Module, pl.LightningModule],
                                   module_name_param_dict: Dict[str, List[Tensor]], optimizers: Optimizer | List[Optimizer]):
        # used in the bind_model process
        def find_param_group(param_groups: List[Dict], module_name: str):
            for i, param_group in enumerate(param_groups):
                params = param_group["params"]
                if isinstance(params, Tensor):
                    params = [params]
                elif isinstance(params, set):
                    raise TypeError('optimizer parameters need to be organized in ordered collections, but '
                                    'the ordering of tensors in sets will change between runs. Please use a list instead.')
                else:
                    params = list(params)
                name_lis = [param2name_dict[id(p)] for p in params if id(p) in param2name_dict]

                for name in name_lis:
                    # match module_name
                    prefix_name = name.strip().split(".")[:-1]
                    prefix_name = ".".join(prefix_name[:-1]) if prefix_name[-1] == '_nni_wrapper' else ".".join(prefix_name)
                    if module_name == prefix_name:
                        return i

            return -1

        def add_param(param_lis: List[Tensor], target_param_group_idx: int, optimizer: Optimizer):
            assert target_param_group_idx < len(optimizer.param_groups)
            target_param_group = optimizer.param_groups[target_param_group_idx]
            for param in param_lis:
                # copyed from torch.optim to check the validation of param
                if not isinstance(param, torch.Tensor):
                    raise TypeError("optimizer can only optimize Tensors, "
                                    "but one of the params is " + torch.typename(param))
                if not optimizer.defaults.get('differentiable', None) \
                    and not (param.is_leaf or param.retains_grad):  # type: ignore
                    raise ValueError("can't optimize a non-leaf Tensor")
                target_param_group['params'].append(param)

        assert isinstance(model, Module)
        param2name_dict = {id(p): name for name, p in model.named_parameters()}
        assert optimizers is not None, "Please provide optimizers for adding param_groups in optimizers"
        optimizers = optimizers if isinstance(optimizers, (list, tuple)) else [optimizers]

        for module_name, param_lis in module_name_param_dict.items():
            is_find_param_group = False
            for optimizer in optimizers:
                param_groups = optimizer.param_groups
                target_param_group_idx = find_param_group(param_groups, module_name)
                if target_param_group_idx >= 0:
                    is_find_param_group = True
                    add_param(param_lis, target_param_group_idx, optimizer)
                    break
            if not is_find_param_group:
                add_param(param_lis, 0, optimizers[0])

def _get_validation_metrics(self):
        # TODO: split metric of multiple models?
        if len(self.metrics) == 1:
            metric_name = next(iter(self.metrics))
            ret = []
            for idx in range(self.n_models):
                ret.append(self.trainer.callback_metrics[f'val_{idx}_' + metric_name].item())
            return ret
        else:
            warnings.warn('Multiple metrics without "default" is not supported by current framework.')
            return {name: self.trainer.callback_metrics['val_' + name].item() for name in self.metrics}

def configure_architecture_optimizers(self):
        ctrl_params = self.arch_parameters()
        if not ctrl_params:
            raise ValueError('No architecture parameters found. Nothing to search.')
        ctrl_optim = torch.optim.Adam(ctrl_params, self.arc_learning_rate, betas=(0.5, 0.999), weight_decay=1.0E-3)

        return ctrl_optim

def aggregate_fn(self, loss: torch.Tensor, normalized_penalty: float) -> torch.Tensor:
        if self.aggregate == 'add':
            return loss + self.scale * normalized_penalty
        if self.aggregate == 'mul':
            return loss * _pow(normalized_penalty + 1, self.scale)
        raise ValueError(f'Invalid aggregate: {self.aggregate}')

def reset_parameters(model, model_init='he_fout', init_div_groups=False,
                     bn_momentum=0.1, bn_eps=1e-5):
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            if model_init == 'he_fout':
                n = m.kernel_size[0] * m.kernel_size[1] * m.out_channels
                if init_div_groups:
                    n /= m.groups
                m.weight.data.normal_(0, math.sqrt(2. / n))
            elif model_init == 'he_fin':
                n = m.kernel_size[0] * m.kernel_size[1] * m.in_channels
                if init_div_groups:
                    n /= m.groups
                m.weight.data.normal_(0, math.sqrt(2. / n))
            else:
                raise NotImplementedError
        elif isinstance(m, nn.BatchNorm2d):
            m.weight.data.fill_(1)
            m.bias.data.zero_()
            m.momentum = bn_momentum
            m.eps = bn_eps
        elif isinstance(m, nn.Linear):
            m.weight.data.normal_(0, 0.01)
            if m.bias is not None:
                m.bias.data.zero_()
        elif isinstance(m, nn.BatchNorm1d):
            m.weight.data.fill_(1)
            m.bias.data.zero_()

def original_state_dict_hooks(model: Any):
    """
    Use this patch if you want to save/load state dict in the original state dict hierarchy.

    For example, when you already have a state dict for the base model / search space (which often
    happens when you have trained a supernet with one-shot strategies), the state dict isn't organized
    in the same way as when a sub-model is sampled from the search space. This patch will help
    the modules in the sub-model find the corresponding module in the base model.

    The code looks like,

    .. code-block:: python

        with original_state_dict_hooks(model):
            model.load_state_dict(state_dict_from_supernet, strict=False)  # supernet has extra keys

    Or vice-versa,

    .. code-block:: python

        with original_state_dict_hooks(model):
            supernet_style_state_dict = model.state_dict()
    """

    import torch.utils.hooks
    import torch.nn as nn
    assert isinstance(model, nn.Module), 'PyTorch is the only supported framework for now.'

    # the following are written for pytorch only

    # first get the full mapping
    full_mapping = {}

    def full_mapping_in_module(src_prefix, tar_prefix, module):
        if hasattr(module, STATE_DICT_PY_MAPPING):
            # only values are complete
            local_map = getattr(module, STATE_DICT_PY_MAPPING)
        elif hasattr(module, STATE_DICT_PY_MAPPING_PARTIAL):
            # keys and values are both incomplete
            local_map = getattr(module, STATE_DICT_PY_MAPPING_PARTIAL)
            local_map = {k: tar_prefix + v for k, v in local_map.items()}
        else:
            # no mapping
            local_map = {}

        if '__self__' in local_map:
            # special case, overwrite prefix
            tar_prefix = local_map['__self__'] + '.'

        for key, value in local_map.items():
            if key != '' and key not in module._modules:  # not a sub-module, probably a parameter
                full_mapping[src_prefix + key] = value

        if src_prefix != tar_prefix:  # To deal with leaf nodes.
            for name, value in itertools.chain(module._parameters.items(), module._buffers.items()):  # direct children
                if value is None or name in module._non_persistent_buffers_set:
                    # it won't appear in state dict
                    continue
                if (src_prefix + name) not in full_mapping:
                    full_mapping[src_prefix + name] = tar_prefix + name

        for name, child in module.named_children():
            # sub-modules
            full_mapping_in_module(
                src_prefix + name + '.',
                local_map.get(name, tar_prefix + name) + '.',  # if mapping doesn't exist, respect the prefix
                child
            )

    full_mapping_in_module('', '', model)

    def load_state_dict_hook(state_dict, prefix, local_metadata, strict, missing_keys, unexpected_keys, error_msgs):
        reverse_mapping = defaultdict(list)
        for src, tar in full_mapping.items():
            reverse_mapping[tar].append(src)

        transf_state_dict = {}
        for src, tar_keys in reverse_mapping.items():
            if src in state_dict:
                value = state_dict.pop(src)
                for tar in tar_keys:
                    transf_state_dict[tar] = value
            else:
                missing_keys.append(src)
        state_dict.update(transf_state_dict)

    def state_dict_hook(module, destination, prefix, local_metadata):
        result = {}
        for src, tar in full_mapping.items():
            if src in destination:
                result[tar] = destination.pop(src)
            else:
                raise KeyError(f'"{src}" not in state dict, but found in mapping.')
        destination.update(result)

    hooks: List[torch.utils.hooks.RemovableHandle] = []
    try:
        hooks.append(model._register_load_state_dict_pre_hook(load_state_dict_hook))
        hooks.append(model._register_state_dict_hook(state_dict_hook))
        yield
    finally:
        for hook in hooks:
            hook.remove()

def new_individual(self) -> ExecutableModelSpace:
        """Get a new sample via mutation from the parent sample."""

        if self.crossover:
            parent1 = self.best_parent()
            parent2 = self.best_parent()
            if set(parent1.keys()) != set(parent2.keys()):
                raise ValueError(f'Parents have different keys: {parent1.keys()} and {parent2.keys()}.')
            # Crossover to get a "parent".
            parent = copy.copy(parent1)
            for key, value in parent2.items():
                # Each dimension has 50% chance to be inherited from parent2.
                if self._random_state.uniform(0, 1) < 0.5:
                    parent[key] = value
        else:
            parent = self.best_parent()

        space = self.model_space.simplify()

        sample = copy.copy(parent)
        for key, mutable in space.items():
            if isinstance(mutable, MutableAnnotation):
                # Skip annotations because resampling them are meaningless.
                continue
            if key not in sample:
                raise KeyError(f'Key {key} not found in parent sample {parent}.')
            if self._random_state.uniform(0, 1) < self.mutation_prob:
                # NOTE: we do not exclude the original choice here for simplicity,
                # which is slightly different from the original paper.
                sample[key] = mutable.random(random_state=self._random_state)

        # Reject duplicate samples here, raise error for retry if duplicate.
        if self._dedup_helper is not None:
            self._dedup_helper.dedup(sample)

        # Reject invalid samples here.
        model = self.model_space.freeze(sample)

        self._individual_counter += 1
        _logger.info('[Individual %4d] Mutated: %s', self._individual_counter, sample)
        return model

def mutate_model(self, model: ModelSpaceType) -> ModelSpaceType:
        # Create architecture parameters beforehand here, in order to save the trouble of creating them inside.
        # It should only be done once because everything else.
        # But sometimes we need to create them inside, e.g., in the cell an extra connection is needed.
        # In these circumstances, they can still go ahead and ignoring the memo.
        self._arch_parameters = {}
        for label, mutable in model.simplify().items():
            if not isinstance(mutable, (Categorical, CategoricalMultiple)):
                raise TypeError(f'Differentiable strategies only support categorical variables, but got {type(mutable)}')
            alpha = nn.Parameter(torch.randn(len(mutable.values)) * 1E-3)
            self._arch_parameters[label] = alpha

        return super().mutate_model(model)

def test(dataloader, model, loss_fn):
    model.eval()
    correct = 0
    with torch.no_grad():
        for X, y in dataloader:
            X, y = X.to(device), y.to(device)
            pred = model(X)
            correct += (pred.argmax(1) == y).type(torch.float).sum().item()
    return correct / len(dataloader.dataset)

