def fit_batch(self, batch):
        """Trains one batch"""
        amp = AMPConfig.from_name(self.precision)
        should_step = (self.step % self.grad_accumulation_factor) == 0

        if self.hparams.use_whamr_train:
            whamr_prob = torch.rand(1).item()
            if whamr_prob > (1 - self.hparams.whamr_proportion):
                batch = next(self.hparams.train_whamr_loader)

        mixture = batch.mix_sig

        targets = [batch.s1_sig, batch.s2_sig]
        if self.hparams.use_wham_noise:
            noise = batch.noise_sig[0]
        else:
            noise = None

        if self.hparams.num_spks == 3:
            targets.append(batch.s3_sig)

        with self.no_sync(not should_step):
            if self.use_amp:
                with torch.autocast(
                    dtype=amp.dtype,
                    device_type=torch.device(self.device).type,
                ):
                    (
                        predictions,
                        snrhat,
                        snr,
                        snr_compressed,
                    ) = self.compute_forward(
                        mixture, targets, sb.Stage.TRAIN, noise
                    )

                    snr = snr.reshape(-1)
                    loss = ((snr_compressed - snrhat).abs()).mean()

                    if (
                        loss.nelement() > 0
                        and loss < self.hparams.loss_upper_lim
                    ):  # the fix for computational problems
                        self.scaler.scale(loss).backward()
                        if self.hparams.clip_grad_norm >= 0:
                            self.scaler.unscale_(self.optimizer)
                            torch.nn.utils.clip_grad_norm_(
                                self.modules.parameters(),
                                self.hparams.clip_grad_norm,
                            )
                        self.scaler.step(self.optimizer)
                        self.scaler.update()
                    else:
                        self.nonfinite_count += 1
                        logger.info(
                            "infinite loss or empty loss! it happened {} times so far - skipping this batch".format(
                                self.nonfinite_count
                            )
                        )
                        loss.data = torch.tensor(0.0).to(self.device)

            else:
                # get the oracle snrs, estimated snrs, and the source estimates
                predictions, snrhat, snr, snr_compressed = self.compute_forward(
                    mixture, targets, sb.Stage.TRAIN, noise
                )

                snr = snr.reshape(-1)
                loss = ((snr_compressed - snrhat).abs()).mean()

                if (
                    loss.nelement() > 0 and loss < self.hparams.loss_upper_lim
                ):  # the fix for computational problems
                    loss.backward()
                    if self.hparams.clip_grad_norm >= 0:
                        torch.nn.utils.clip_grad_norm_(
                            self.modules.parameters(),
                            self.hparams.clip_grad_norm,
                        )
                    self.optimizer.step()
                else:
                    self.nonfinite_count += 1
                    logger.info(
                        "infinite loss or empty loss! it happened {} times so far - skipping this batch".format(
                            self.nonfinite_count
                        )
                    )
                    loss.data = torch.tensor(0.0).to(self.device)

        self.optimizer.zero_grad()

        return loss.detach().cpu()

def on_stage_start(self, stage, epoch):
        """Gets called at the beginning of each epoch"""
        if stage != sb.Stage.TRAIN:
            # Define function taking (prediction, target) for parallel eval
            def pesq_eval(pred_wav, target_wav):
                """Computes the PESQ evaluation metric"""
                psq_mode = (
                    "wb" if self.hparams.enhance_sample_rate == 16000 else "nb"
                )
                try:
                    return pesq(
                        fs=self.hparams.enhance_sample_rate,
                        ref=target_wav.numpy(),
                        deg=pred_wav.numpy(),
                        mode=psq_mode,
                    )
                except Exception:
                    print("pesq encountered an error for this data item")
                    return 0

            self.pesq_metric = MetricStats(
                metric=pesq_eval, n_jobs=1, batch_eval=False
            )
            self.cer_metric = self.hparams.cer_computer()
            self.wer_metric = self.hparams.error_rate_computer()

        # Freeze models before training
        else:
            for model in self.hparams.frozen_models:
                if (
                    hasattr(self.hparams, "unfreeze_epoch")
                    and epoch >= self.hparams.unfreeze_epoch
                    and (
                        not hasattr(self.hparams, "unfrozen_models")
                        or model in self.hparams.unfrozen_models
                    )
                ):
                    self.modules[model].train()
                    for p in self.modules[model].parameters():
                        p.requires_grad = True  # Model's weight will be updated
                else:
                    self.modules[model].eval()
                    for p in self.modules[model].parameters():
                        p.requires_grad = False

def dataio_prep(hparams):
    @sb.utils.data_pipeline.takes("Show", "EpId", "ClipId")
    @sb.utils.data_pipeline.provides("id", "waveform")
    def audio_pipeline(Show, EpId, ClipId):
        EpId = int(EpId)
        file = f"{hparams['data_folder']}/sep28k_clips/{Show}/{EpId}/{Show}_{EpId}_{ClipId}.wav"
        waveform, _ = torchaudio.load(file, normalize=True)
        return (EpId, int(ClipId)), waveform.squeeze()

    @sb.utils.data_pipeline.takes(
        "Prolongation",
        "Block",
        "SoundRep",
        "WordRep",
        "Interjection",
        "NoStutteredWords",
    )
    @sb.utils.data_pipeline.provides("label", "unsure")
    def get_label(p, b, sr, wr, inter, f):
        label, unsure = get_labels(p, b, sr, wr, inter, f)
        return label, unsure

    datasets = {}
    for dataset in ["train", "valid", "test"]:
        hparams["train_logger"].log_stats(stats_meta={"Processing": dataset})
        datasets[f"{dataset}"] = sb.dataio.dataset.DynamicItemDataset.from_csv(
            csv_path=hparams[f"{dataset}_csv"],
            dynamic_items=[audio_pipeline, get_label],
            output_keys=["id", "waveform", "label", "unsure"],
        )

        if hparams["remove_unsure"]:
            counter_u = 0
            for i in range(len(datasets[dataset])):
                if datasets[dataset][i]["unsure"] == 1:
                    counter_u += 1
            d = datasets[dataset].filtered_sorted(
                sort_key="unsure",
                reverse=True,
                select_n=len(datasets[dataset]) - counter_u,
            )
            datasets[dataset] = d
        hparams["train_logger"].log_stats(
            stats_meta={f"{dataset} samples": len(datasets[dataset])}
        )
    return datasets

def compute_objectives(self, predictions, batch, stage):
        """Computes the loss (NLL) given predictions and targets."""

        p_seq, wav_lens, predicted_tokens = predictions

        ids = batch.id
        tokens_eos, tokens_eos_lens = batch.tokens_eos
        tokens, tokens_lens = batch.tokens

        if stage == sb.Stage.TRAIN and hasattr(self.hparams, "wav_augment"):
            tokens_eos = self.hparams.wav_augment.replicate_labels(tokens_eos)
            tokens_eos_lens = self.hparams.wav_augment.replicate_labels(
                tokens_eos_lens
            )

        loss_seq = self.hparams.seq_cost(
            p_seq, tokens_eos, length=tokens_eos_lens
        )

        # (No ctc loss)
        loss = loss_seq

        if (stage != sb.Stage.TRAIN) or (self.step % show_results_every == 0):
            # Decode token terms to words
            predicted_semantics = [
                tokenizer.decode_ids(utt_seq).split(" ")
                for utt_seq in predicted_tokens
            ]

            target_semantics = [wrd.split(" ") for wrd in batch.semantics]

            self.log_outputs(predicted_semantics, target_semantics)

            if stage != sb.Stage.TRAIN:
                self.wer_metric.append(
                    ids, predicted_semantics, target_semantics
                )
                self.cer_metric.append(
                    ids, predicted_semantics, target_semantics
                )

            if stage == sb.Stage.TEST:
                # write to "predictions.jsonl"
                with jsonlines.open(
                    hparams["output_folder"] + "/predictions.jsonl", mode="a"
                ) as writer:
                    for i in range(len(predicted_semantics)):
                        try:
                            _dict = ast.literal_eval(
                                " ".join(predicted_semantics[i]).replace(
                                    "|", ","
                                )
                            )
                            if not isinstance(_dict, dict):
                                _dict = {
                                    "scenario": "none",
                                    "action": "none",
                                    "entities": [],
                                }
                        # need this if the output is not a valid dictionary
                        except SyntaxError:
                            _dict = {
                                "scenario": "none",
